exercises.solution:
using System.Collections.Generic;

var s = new List<int>(10);
s.Add(0); s.Add(0); s.Add(0);
Console.WriteLine($"{s.Count} {s.Capacity}");

var n = new[] { 1, 2, 3, 4, 5 };
